<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$project=(int)($_GET['project_id']??$_POST['project_id']??0);if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['staff_id'])){$q=$db->prepare('INSERT INTO project_resources(project_id,staff_id,role_name,allocation_percent,start_date,end_date) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE role_name=VALUES(role_name),allocation_percent=VALUES(allocation_percent),start_date=VALUES(start_date),end_date=VALUES(end_date),status="active"');$q->execute([$project,(int)$_POST['staff_id'],trim($_POST['role_name']??''),(float)($_POST['allocation_percent']??100),$_POST['start_date']?:null,$_POST['end_date']?:null]);header('Location: project-resources.php?project_id='.$project);exit;}$staff=$db->query("SELECT id,employee_code,first_name,last_name,job_title FROM staff_members WHERE employment_status='active' ORDER BY first_name")->fetchAll();$resources=$db->prepare('SELECT r.*,s.employee_code,s.first_name,s.last_name,s.job_title FROM project_resources r JOIN staff_members s ON s.id=r.staff_id WHERE r.project_id=? ORDER BY s.first_name');$resources->execute([$project]);$resources=$resources->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project Resources</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Project Resources</h1><div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><input type="hidden" name="project_id" value="<?=$project?>"><div class="col-md-4"><select class="form-select" name="staff_id" required><option value="">Select staff</option><?php foreach($staff as $s):?><option value="<?=$s['id']?>"><?=$e($s['employee_code'].' — '.$s['first_name'].' '.$s['last_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><input class="form-control" name="role_name" placeholder="Project role"></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" name="allocation_percent" value="100"></div><div class="col-md-3"><input class="form-control" type="date" name="start_date"></div><div class="col-md-3"><input class="form-control" type="date" name="end_date"></div><div class="col-12"><button class="btn btn-dark">Assign Resource</button></div></form></div></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Staff</th><th>Role</th><th>Allocation</th><th>Period</th><th>Status</th></tr></thead><tbody><?php foreach($resources as $r):?><tr><td><?=$e($r['first_name'].' '.$r['last_name'])?></td><td><?=$e($r['role_name'])?></td><td><?=$e($r['allocation_percent'])?>%</td><td><?=$e($r['start_date'])?> → <?=$e($r['end_date'])?></td><td><?=$e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>